"""Read existing anonymous results once; no medical inference or method selection."""
import json,time
from pathlib import Path
from collect_gain_joint import CANDIDATES,HEADS,FIELDS,delta,table,csvwrite,dump

def summarize(round_dir,reporting_commit):
    started=time.monotonic();r=Path(round_dir);out=r/'results';s=json.loads((out/'RESULTS.json').read_text());lock=json.loads((r/'PROTOCOL_LOCK.json').read_text());final=[];stages=[];selection_rows=[];gate_counts={k:dict(admissible=0,admissible_actual_positive=0,admissible_actual_negative=0,rejected_actual_positive=0,rejected_actual_negative=0) for k in ('point','predictive')};interval_counts={k:dict(below=0,inside=0,above=0) for k in gate_counts};distribution=dict(positive=0,zero=0,negative=0);chosen={k:dict(positive=0,zero=0,negative=0) for k in ('JOINT_POINT_SELECTED','JOINT_PRED_SELECTED')};all_negative=[]
    def sign(v):return 'positive' if v>1e-10 else 'negative' if v< -1e-10 else 'zero'
    for n,run in s['runs'].items():
        for st,prep in zip(run['stages'],s['prepared'][n]['stages']):
            seen=st['heads']['C1']['metrics']['OFF']['seen'];values=[]
            def actual(head):
                a=st['heads'][head];p=[a['paired'][str(c)] for c in seen];net=sum(z['net_correct']/z['n'] for z in p)/len(p);assert abs(net-(a['metrics']['ON']['balanced_accuracy']-a['metrics']['OFF']['balanced_accuracy']))<1e-12;assert sum(z['rescued'] for z in p)==a['paired']['all']['rescued'] and sum(z['harmed'] for z in p)==a['paired']['all']['harmed'];return a,p,net
            for head in CANDIDATES:
                a,p,net=actual(head);m=prep['variants'][head]['mechanical'];point=m['point'];pred=m['predictive'];unknown=pred['scenarios'][0]['unknown_mass'];centers=[z['known_net'] for z in pred['scenarios']];bias=[v-net for v in centers];values.append(net)
                row=dict(job=n,task=st['task'],head=head,rescued=a['paired']['all']['rescued'],harmed=a['paired']['all']['harmed'],macro_rescue_pp=100*sum(z['rescued']/z['n'] for z in p)/len(p),macro_harm_pp=100*sum(z['harmed']/z['n'] for z in p)/len(p),actual_net_pp=100*net,new_rescued=a['paired']['new']['rescued'],new_harmed=a['paired']['new']['harmed'],pred_known_center_min_pp=100*min(centers),pred_known_center_max_pp=100*max(centers),pred_sensitivity_lower_pp=100*pred['robust_lower'],pred_sensitivity_upper_pp=100*pred['robust_upper'],unknown_mass_pp=100*unknown,full_center_available=not bool(unknown),full_bias_min_pp=None if unknown else 100*min(bias),full_bias_max_pp=None if unknown else 100*max(bias),known_partial_minus_full_actual_min_pp=100*min(bias),known_partial_minus_full_actual_max_pp=100*max(bias),point_lower_pp=100*point['robust_lower'],point_upper_pp=100*point['robust_upper'])
                stages.append(row)
                if st['task']==len(run['stages']):final.append(row)
                if st['task']>1:
                    distribution[sign(100*net)]+=1
                    for estimator in gate_counts:
                        model=m[estimator];accept=model['robust_lower']>1e-12;gate_counts[estimator]['admissible']+=int(accept);gate_counts[estimator][('admissible' if accept else 'rejected')+'_actual_'+sign(100*net)]+=1
                        for z in model['scenarios']:interval_counts[estimator]['below' if net<z['net_lower'] else 'above' if net>z['net_upper'] else 'inside']+=1
            if st['task']>1 and max(values)<0:all_negative.append(dict(job=n,task=st['task']))
            for estimator in chosen:
                a,p,net=actual(estimator);selection_rows.append(dict(job=n,task=st['task'],selection=estimator,scale=prep['selections'][estimator]['chosen_scale'],actual_net_pp=100*net,rescued=a['paired']['all']['rescued'],harmed=a['paired']['all']['harmed']))
                if st['task']>1:chosen[estimator][sign(100*net)]+=1
    assert len(stages)==72 and len(final)==16 and sum(distribution.values())==56 and all(a['new_harmed']==0 for a in stages)
    main_delta=[];gap=[]
    for n,run in s['runs'].items():
        off=run['control_metrics'];on=run['metrics']['JOINT_PRED_SELECTED']['guarded'];diff=delta(on,off);main_delta.append(dict(job=n,**{k:diff[k] for k in FIELDS}));air=lock['AIR_references'][run['dataset']]['final_balanced_accuracy'];gap.append(dict(job=n,OFF_AIR_gap_pp=100*(air-off[FIELDS[0]]),JOINT_PRED_AIR_gap_pp=100*(air-on[FIELDS[0]]),gap_reduction_pp=100*(on[FIELDS[0]]-off[FIELDS[0]])))
    diagnosis=dict(status='COMPLETE',reporting_source_commit=reporting_commit,source_commit=json.loads((out/'AUDIT.json').read_text())['source_commit'],candidate_outcomes_nonfirst=distribution,gate_admission_counts=gate_counts,chosen_outcomes_nonfirst=chosen,all_four_candidates_negative_states=all_negative,interval_comparisons_nonfirst=interval_counts,interval_inclusion_not_confidence_coverage=True,final_candidates=final,stage_candidates=stages,selections=selection_rows,main_six_metric_deltas=main_delta,AIR_gap=gap,all_current_new_harmed_zero=True,medical_reevaluation=False,optimizer_updates=0,test_accessed=False)
    dump(out/'DIAGNOSTIC_SUMMARY.json',diagnosis);csvwrite(out/'FINAL_CANDIDATES.csv',final);csvwrite(out/'STAGE_CANDIDATES.csv',stages)
    lines=['# 同状态诊断结论与全部候选','', '四准备/18stage/72sidecar、四真实零更新PASS、四评价COMPLETE与8GPU costs均核对通过，active空且进程退出后才收集。测试封存，无重训或调参。','', '**结论：旧门确实过于保守，但新版门已不是主要拒绝瓶颈；固定方向在许多状态有害，联合模型对实际纠错的预测与排序仍不可靠。** 非首stage56候选15正/41负；旧选择全部identity拒绝15个实际正候选。新点/预测门各允许38候选，其中15正/23负，未拒绝任何实际正候选；新规则均在14个非首stage选非零，7正/7负。存在6个状态四步长全负，不能靠放宽门获得本组候选的净收益。','现有证据限定于固定四候选及此development val，不代表所有可能方向或步长无效，也不把观察到的最优候选改为方法。', '']
    lines+=['## 最终四候选实际纠错与预测(pp)','救回/破坏是图数；macro净值按每类n加权，因此救回图数更多仍可降低BA。HK未知质量非零，完整中心/总体偏差留null；部分估计减全体实际值仅供分解，不称总体偏差。各情景完整Gaussian/Student-t值与class偏差见ESTIMATE_BIAS/CLASS_ESTIMATES。']
    table(lines,list(final[0]),final);lines+=['','## 18stage四候选全部正负'];table(lines,['job','task','head','rescued','harmed','macro_rescue_pp','macro_harm_pp','actual_net_pp','new_rescued','new_harmed'],stages);lines+=['','## 所有预val选择与实际结果'];table(lines,list(selection_rows[0]),selection_rows);lines+=['','## 固定预测选择相对各自控制的六指标增量(pp；forget上升不利)'];table(lines,list(main_delta[0]),main_delta);lines+=['','## AIR BA差距'];table(lines,list(gap[0]),gap)
    lines+=['','## 联合估计与准入的失配','ISIC_base最终λ=.5，实际+.315120pp，预测中心+2.211851..+2.236592pp，乐观偏差+1.896731..+1.921473pp。ISIC_LT同λ=.5实际−.111462pp，预测+2.231980..+2.246214pp，乐观偏差+2.343442..+2.357675pp；实际λ=.125为+.345460pp，新规则却选择λ=.5。该状态重点是预测/排序失配，而不是继续降低准入阈值。','HK最终λ=.125：base实际+.059890pp，LT实际−.725558pp；已识别质量预测分别+3.677493..+3.811716、+3.637545..+3.763086pp，完整中心不提供。未识别质量仅.077488pp，数值半宽约.304..305pp，而模型净区间仍全部为正，不能用这两项解释与实际的约3.6..4.5pp差。','非首阶段168情景比较：Gaussian实际落入3、下方153、上方12；Student-t落入4、下方152、上方12。这不是医学置信覆盖率检验，只证明声明的假设模型情景与此val实际变化常不一致。积分数值误差界不覆盖模型失配。Student-t与借用三情景的变化远不足以消除这些差异。', '','## 方向、旧新类与守卫','6个全负状态为ISIC_LT T2，HK_base T4/T5，HK_LT T4/T5/T6。HK λ=.5/1严重破坏旧类；λ=.125虽多救回图像，稀少类别的损失仍可抵消全部宏收益。','HK_LT λ=.125救回37/破坏17，Acc+1.177856pp却BA−.725558pp。class20救回13/66、class11救回9/61；class0破坏2/7(−28.571429pp)、class17破坏1/5(−20pp)，class22破坏2/21仅救1/21。模型对class16预测约+17.998pp而实际0，对class0预测约+11.139pp而实际−28.571pp，对class17仅预测−.478pp而实际−20pp。class20/11有未知统计质量，所列对应预测为部分量。连续小n统计按协议抑制，离散分母与计数保留。','最终ISIC λ=.5：两控制各救回新类4、破坏0，新recall各+4.886364pp；但旧class4均破坏7/41，class6均破坏2/26，LT的class5救3/破5，使tail分别−6.557361/−7.542721pp。HK预测选择新类破坏0，base新类不变、LT救回1/310，但仍不能保护全部旧类。','守卫在最终ISIC两控制分别避免1/2个RAW新类破坏，同时各挡住3个旧类潜在救回；HK最终λ=.125 base挡住1个旧救回，LT没有挡住旧救回。因此HK_LT该步长的净下降不能归因于守卫拦掉救回；边界重排本身已经伤害稀少旧类。完整RAW/守卫对照均保留，守卫不能保护precision或修复新新混淆。','', '## 费用与工程边界','GPU驻留692.971862659秒(4预检+4评价)，4实际checkpoint CPU准备2393.983148159秒；启动前合成CPU403.362191442秒独立列示，所有pipeline已包含于对应驻留。墙钟1553.090406656秒，即25分53秒。历史闭合GPU327972.4417148675秒，本轮后328665.4135775268秒；旧控制/AIR/旧GAIN复用0收费，历史设计29.468065921秒不重计。','正式流程无失败/0optimizer/0policy/testfalse。collector首次本地导入间接依赖Torch失败，发生于远程收集前，无模型/图像/额外GPU。仅报告层隔离常量修复，冻结运行源未改，未重评；未单测该本地失败及报告进程驻留，不虚填0。','0新实验/0后验调参。当前结果不支持将此准入当作可靠的净类均衡收益证书；有正候选不能遮盖其他负状态、tail/forget和AIR差距恶化。单seed/order反复development val，不作临床或独立患者结论。']
    text='\n'.join(lines)+'\n';(out/'INTERPRETATION_ZH.md').write_text(text);report=(out/'REPORT_ZH.md').read_text();marker='<!-- COMPLETE_CANDIDATE_DIAGNOSIS -->';assert marker not in report;(out/'REPORT_ZH.md').write_text(marker+'\n'+text+'\n---\n\n'+report)
    audit=json.loads((out/'AUDIT.json').read_text());audit.update(reporting_source_commit=reporting_commit,anonymous_collection_source_commit_before_reporting_fix=audit['reporting_source_commit'],report_only_dependency_fix=True,report_CPU_process_residence_seconds=None,all_72_candidate_net_matches_BA_delta=True,diagnostic_summary_counts_verified=True);dump(out/'AUDIT.json',audit);return dict(status='PASS',candidate_rows=72,final_rows=16,candidate_signs=distribution,admission=gate_counts,chosen=chosen,model_interval_comparisons=interval_counts,local_analysis_pipeline_seconds=time.monotonic()-started,medical_reevaluation=False)
if __name__=='__main__':
    import sys
    print(json.dumps(summarize(sys.argv[1],sys.argv[2]),indent=2))
